using System.Security.Cryptography;

namespace Crap4CSharp.Core;

// Private authored-input gate. Generated bytes and actual Csc reference/output binding require
// independent phase-C reconciliation; this gate alone never asserts compiled/reusable capability.
internal sealed class CompilerPhaseSnapshot
{
    internal const long MaximumFileBytes = 64 * 1024 * 1024;
    internal const long MaximumClosureBytes = 512 * 1024 * 1024;
    internal const int MaximumInputs = 32768;
    private readonly Dictionary<InputKey, FileIdentity> inputs;
    private CompilerPhaseSnapshot(Dictionary<InputKey, FileIdentity> inputs) => this.inputs = inputs;

    internal static CompilerPhaseSnapshot Capture(ProjectContextLoadResult loaded, CancellationToken token) =>
        new(Read(loaded, token));

    internal void Validate(ProjectContextLoadResult current, CancellationToken token)
    {
        var after = Read(current, token);
        if (inputs.Count != after.Count || inputs.Any(p => !after.TryGetValue(p.Key, out var value) || value != p.Value))
            throw Refuse("Authored/prepared input bytes, timestamps, roles or membership changed during execution.");
    }

    private static Dictionary<InputKey, FileIdentity> Read(ProjectContextLoadResult loaded, CancellationToken token)
    {
        token.ThrowIfCancellationRequested();
        if (!loaded.Success || loaded.GraphContexts.Count == 0 || loaded.GraphContexts.Count > 4096 ||
            loaded.GraphContexts.Select(b => b.GraphId).Distinct(StringComparer.Ordinal).Count() != loaded.GraphContexts.Count)
            throw Refuse("Phase snapshot requires a successful uniquely bound graph.");
        var result = new Dictionary<InputKey, FileIdentity>();
        var cache = new Dictionary<string, FileIdentity>(OperatingSystem.IsWindows() ? StringComparer.OrdinalIgnoreCase : StringComparer.Ordinal);
        long totalBytes = 0;
        var count = 0;
        foreach (var binding in loaded.GraphContexts)
        {
            foreach (var input in binding.Context.PhaseInputs.ToArray())
            {
                token.ThrowIfCancellationRequested();
                if (++count > MaximumInputs) throw Limit();
                if (string.IsNullOrWhiteSpace(binding.GraphId) || !Path.IsPathFullyQualified(input.Path) || input.Path != Path.GetFullPath(input.Path) ||
                    input.Role is not ("source" or "project" or "import" or "additionalFile" or "analyzerConfig" or "analyzer" or "restoreAssets" or "sdkConfiguration" or "analyzerConfigProbe"))
                    throw Refuse("Input paths and roles must be explicit and canonical.");
                if (input.ExpectedGenerated)
                {
                    if (input.Role is not ("source" or "analyzerConfig")) throw Refuse("Immutable input roles cannot become generated transitions.");
                    continue;
                }
                if (!cache.TryGetValue(input.Path, out var identity))
                {
                    identity = ReadFile(input.Path, token, input.Role == "analyzerConfigProbe");
                    totalBytes = checked(totalBytes + identity.Length);
                    if (totalBytes > MaximumClosureBytes) throw Limit();
                    cache.Add(input.Path, identity);
                }
                var key = new InputKey(binding.GraphId, OperatingSystem.IsWindows() ? input.Path.ToUpperInvariant() : input.Path, input.Role);
                result.TryAdd(key, identity); // One physical file may legitimately have several roles/contexts.
            }
        }
        return result;
    }

    private static FileIdentity ReadFile(string path, CancellationToken token, bool absenceProbe)
    {
        try
        {
            if (absenceProbe && !File.Exists(path) && !Directory.Exists(path))
            {
                // GetAttributes distinguishes true absence from a broken symlink or inaccessible path.
                try { _ = File.GetAttributes(path); }
                catch (FileNotFoundException) { return new("absent", 0, 0); }
                catch (DirectoryNotFoundException) { return new("absent", 0, 0); }
            }
            for (var current = path; current is not null; current = Path.GetDirectoryName(current))
                if ((File.GetAttributes(current) & FileAttributes.ReparsePoint) != 0)
                    throw Refuse("Phase inputs cannot traverse reparse points.");
            if (!ArtifactBundle.IsRegularInput(path)) throw Refuse("Phase inputs must be regular files.");
            var time = File.GetLastWriteTimeUtc(path).Ticks;
            using var stream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read, 65536, FileOptions.SequentialScan);
            if (!stream.CanSeek) throw Refuse("Phase inputs must be seekable regular files.");
            var length = stream.Length;
            if (length > MaximumFileBytes) throw Limit();
            using var hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
            var buffer = new byte[65536];
            long count = 0;
            while (true)
            {
                token.ThrowIfCancellationRequested();
                var read = stream.Read(buffer, 0, buffer.Length);
                if (read == 0) break;
                count += read;
                if (count > MaximumFileBytes) throw Limit();
                hash.AppendData(buffer, 0, read);
            }
            if (count != length || stream.Length != length || File.GetLastWriteTimeUtc(path).Ticks != time)
                throw Refuse("An input changed while its phase identity was read.");
            return new(Convert.ToHexString(hash.GetHashAndReset()).ToLowerInvariant(), length, time);
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException)
        { throw Refuse("A phase input disappeared or became unreadable."); }
    }

    private sealed record InputKey(string GraphId, string Path, string Role);
    private sealed record FileIdentity(string Sha256, long Length, long MtimeTicks);
    private static ProjectContextException Refuse(string message) => new("compiler.inputsMutated", message);
    private static ProjectContextException Limit() => new("compiler.inputLimit", "The private phase input count or byte limit was exceeded.");
}
